<template><div class="module-page"><div class="page-header-row"><div><span class="eyebrow">প্রশাসনিক বিভাগ</span><h1>স্টাফ ও কর্মী</h1><p>কর্মী, দায়িত্ব, বিভাগ ও বেতন তথ্য পরিচালনা করুন</p></div><button class="btn btn-primary" @click="showForm=!showForm"><icon name="plus" /> নতুন স্টাফ</button></div><div class="toolbar card"><div class="search-box"><icon name="search" /><input v-model="search" placeholder="নাম খুঁজুন..." @keyup.enter="load" /></div><button class="btn btn-outline btn-sm" @click="load"><icon name="refresh" /> রিফ্রেশ</button></div><form v-if="showForm" class="create-panel card" @submit.prevent="createStaff"><div class="form-heading"><h2>নতুন স্টাফ যোগ করুন</h2><button type="button" class="close-btn" @click="showForm=false">×</button></div><div v-if="error" class="alert alert-error">{{ error }}</div><div class="form-grid"><div class="form-group"><label>নাম *</label><input v-model="form.name_bn" class="form-control" required /></div><div class="form-group"><label>ইমেইল</label><input v-model="form.email" type="email" class="form-control" /></div><div class="form-group"><label>ফোন</label><input v-model="form.phone" class="form-control" /></div><div class="form-group"><label>পদবি</label><input v-model="form.designation" class="form-control" /></div><div class="form-group"><label>বিভাগ</label><input v-model="form.department" class="form-control" /></div><div class="form-group"><label>যোগদানের তারিখ</label><input v-model="form.join_date" type="date" class="form-control" /></div><div class="form-group"><label>বেতন</label><input v-model.number="form.salary" type="number" class="form-control" /></div></div><div class="form-actions"><button class="btn btn-primary" :disabled="saving">{{ saving?'সংরক্ষণ হচ্ছে...':'স্টাফ যোগ করুন' }}</button><button type="button" class="btn btn-ghost" @click="showForm=false">বাতিল</button></div></form><div v-if="loading" class="loading-state"><div class="spinner" /></div><div v-else-if="!staff.length" class="empty-card"><div class="empty-icon"><icon name="users" /></div><h3>কোনো স্টাফ রেকর্ড নেই</h3><p>প্রশাসনিক টিম যোগ করে কর্মী ব্যবস্থাপনা শুরু করুন</p></div><div v-else class="staff-grid"><article v-for="person in staff" :key="person.id" class="staff-card"><div class="person-avatar">{{ (person.name_bn||person.user?.name_bn||'স').charAt(0) }}</div><div class="person-copy"><h3>{{ person.name_bn || person.user?.name_bn }}</h3><p>{{ person.designation || 'পদবি নির্ধারিত নয়' }}</p><span>{{ person.department || 'বিভাগ নির্ধারিত নয়' }}</span></div><div class="staff-status" :class="person.is_active===false?'off':'on'">{{ person.is_active===false?'নিষ্ক্রিয়':'সক্রিয়' }}</div><div class="staff-meta"><span>{{ person.phone || 'ফোন নেই' }}</span><span>{{ person.join_date ? formatDate(person.join_date) : 'তারিখ নেই' }}</span></div></article></div></div></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{useApiClient}from'~/utils/api';const api=useApiClient();const staff=ref<any[]>([]);const loading=ref(true);const saving=ref(false);const showForm=ref(false);const error=ref('');const search=ref('');const form=reactive({name_bn:'',email:'',phone:'',designation:'',department:'',join_date:'',salary:0});async function load(){loading.value=true;try{const q=search.value?`?search=${encodeURIComponent(search.value)}`:'';const r=await api.get(`/hr/staff${q}`);staff.value=r.data?.data?.data||r.data?.data||[]}catch(e){console.error(e)}finally{loading.value=false}}async function createStaff(){saving.value=true;error.value='';try{await api.post('/hr/staff',form);showForm.value=false;form.name_bn='';form.email='';form.phone='';form.designation='';form.department='';await load()}catch(e:any){error.value=e?.response?.data?.message||'স্টাফ তৈরি করা যায়নি'}finally{saving.value=false}}function formatDate(v:string){return new Date(v).toLocaleDateString('bn-BD',{day:'numeric',month:'short',year:'numeric'})}onMounted(load)</script>
<style scoped>.module-page{max-width:1400px;margin:0 auto;padding-bottom:2rem}.page-header-row{display:flex;justify-content:space-between;align-items:flex-end;gap:1rem;margin-bottom:1.4rem}.eyebrow{color:var(--color-primary);font:600 .78rem var(--font-bn)}.page-header-row h1{margin:.25rem 0;color:var(--color-primary);font:700 1.65rem var(--font-bn)}.page-header-row p{color:var(--color-text-light);font:.88rem var(--font-bn)}.toolbar{display:flex;gap:.7rem;padding:.7rem;margin-bottom:1rem}.search-box{display:flex;align-items:center;gap:.5rem;flex:1;padding:0 .75rem;background:var(--color-bg-muted);border-radius:10px}.search-box input{width:100%;padding:.65rem 0;border:0;outline:0;background:transparent;font:.86rem var(--font-bn)}.create-panel{padding:1.2rem;margin-bottom:1rem}.form-heading{display:flex;justify-content:space-between;margin-bottom:1rem}.form-heading h2{font:700 1rem var(--font-bn)}.close-btn{border:0;background:transparent;font-size:1.5rem;color:var(--color-text-muted);cursor:pointer}.form-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:.7rem}.form-group label{display:block;margin-bottom:.3rem;font:600 .78rem var(--font-bn)}.form-actions{display:flex;gap:.6rem;margin-top:1rem}.staff-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem}.staff-card{position:relative;display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:.75rem;padding:1.1rem;background:#fff;border:1px solid var(--color-border-light);border-radius:17px;box-shadow:var(--shadow-sm);transition:.2s}.staff-card:hover{transform:translateY(-3px);box-shadow:var(--shadow-md)}.person-avatar{display:grid;place-items:center;width:48px;height:48px;border-radius:15px;color:#fff;background:linear-gradient(145deg,#176b45,#0e452d);font:700 1.1rem var(--font-bn)}.person-copy h3{color:var(--color-text);font:700 .9rem var(--font-bn)}.person-copy p,.person-copy span{display:block}.person-copy p{margin-top:.15rem;color:var(--color-text-light);font:.75rem var(--font-bn)}.person-copy span{margin-top:.15rem;color:var(--color-text-muted);font:.68rem var(--font-bn)}.staff-status{padding:.24rem .55rem;border-radius:99px;font:.65rem var(--font-bn)}.staff-status.on{color:#19724a;background:#e6f4ec}.staff-status.off{color:#a05c35;background:#fff0e4}.staff-meta{grid-column:1/-1;display:flex;justify-content:space-between;padding-top:.75rem;border-top:1px solid var(--color-border-light);color:var(--color-text-muted);font:.68rem var(--font-bn)}.empty-card{padding:3rem;text-align:center;background:#fff;border:1px dashed var(--color-border);border-radius:18px}.empty-icon{display:grid;place-items:center;width:54px;height:54px;margin:0 auto 1rem;border-radius:16px;color:var(--color-primary);background:var(--color-primary-50);font-size:1.4rem}.empty-card h3{font:700 1rem var(--font-bn)}.empty-card p{color:var(--color-text-light);font:.8rem var(--font-bn)}@media(max-width:1000px){.staff-grid{grid-template-columns:repeat(2,1fr)}.form-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:650px){.page-header-row{align-items:flex-start;flex-direction:column}.staff-grid,.form-grid{grid-template-columns:1fr}}
</style>
